(function() {
    'use strict';

    class GlobalTalentAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'GlobalTalent: Expatriate Management';
            this.version = '1.1.0';

            this.MARKET_PROFILES = {
                sg: { name: 'Singapore', culturalDistance: 4.2, ltaCost: 280000, shortCost: 120000, virtualCost: 35000, localCost: 90000, ltaKT: 90, shortKT: 60, virtualKT: 30, localKT: 45, ccaBase: 72 },
                du: { name: 'Dubai', culturalDistance: 6.8, ltaCost: 320000, shortCost: 140000, virtualCost: 35000, localCost: 80000, ltaKT: 85, shortKT: 55, virtualKT: 25, localKT: 40, ccaBase: 55 },
                nbi: { name: 'Nairobi', culturalDistance: 5.9, ltaCost: 300000, shortCost: 110000, virtualCost: 30000, localCost: 70000, ltaKT: 80, shortKT: 50, virtualKT: 20, localKT: 35, ccaBase: 60 }
            };

            this.COMP_MODIFIERS = {
                balancesheet: { costMult: 1.0, retention: 15, equity: 10 },
                localplus: { costMult: 0.7, retention: 5, equity: -5 },
                lumpsum: { costMult: 0.8, retention: 0, equity: 0 }
            };

            this.CORRECTION_EFFECTS = {
                maintain: { cost: 0, kt: 0, localLeg: 0, ccaBoost: 0 },
                strengthen: { cost: 40000, kt: 15, localLeg: -5, ccaBoost: 5 },
                localize: { cost: -30000, kt: -10, localLeg: 20, ccaBoost: 10 },
                reassign: { cost: 80000, kt: -25, localLeg: 5, ccaBoost: -15 }
            };

            this.EVENTS = [
                {
                    sg: 'Singapore: Employment Pass delay triggered by Fair Consideration Framework. 6-week launch delay applies.',
                    du: 'Dubai: Emiratisation audit triggered. Two Emirati hires required within 90 days or face fines.',
                    nbi: 'Nairobi: Class G Work Permit rejection. Role deemed fillable by a local candidate. 10-week delay.'
                },
                {
                    sg: 'Singapore: Trailing spouse unable to find work. Expatriate has requested an early return discussion.',
                    du: 'Dubai: Cultural incident. Direct communication style offended a senior client who threatens to disengage.',
                    nbi: 'Nairobi: General election triggers 6-week business disruption and elevated security concerns.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalBudget: 2800000,
                    budgetRemaining: 2800000,
                    assignmentBudget: 2100000,
                    culturalBudget: 320000,
                    repatBudget: 180000,
                    adminBudget: 200000,

                    sg: { knowledgeTransfer: 0, ccaScore: 0, localLegitimacy: 30, assignmentType: '', costSpent: 0 },
                    du: { knowledgeTransfer: 0, ccaScore: 0, localLegitimacy: 30, assignmentType: '', costSpent: 0 },
                    nbi: { knowledgeTransfer: 0, ccaScore: 0, localLegitimacy: 30, assignmentType: '', costSpent: 0 },

                    marketLaunchScore: 0,
                    talentRetention: 75,
                    totalCostScore: 100,
                    crossCulturalIncidents: 0,
                    globalIntegration: 0,

                    globalScoreHistory: [],
                    costHistory: [],
                    retentionHistory: [],

                    currentEvent: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sgAssignment: 'lta',
                    sgCompensation: 'balancesheet',
                    sgPreDeparture: 15000,
                    duAssignment: 'lta',
                    duCompensation: 'balancesheet',
                    duPreDeparture: 15000,
                    nbiAssignment: 'lta',
                    nbiCompensation: 'balancesheet',
                    nbiPreDeparture: 20000
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;

            if (period === 1) {
                var sgA = document.getElementById('sgAssignment');
                var sgC = document.getElementById('sgCompensation');
                var sgP = document.getElementById('sgPreDeparture');
                var duA = document.getElementById('duAssignment');
                var duC = document.getElementById('duCompensation');
                var duP = document.getElementById('duPreDeparture');
                var nbiA = document.getElementById('nbiAssignment');
                var nbiC = document.getElementById('nbiCompensation');
                var nbiP = document.getElementById('nbiPreDeparture');

                if (sgA) decisions.sgAssignment = sgA.value;
                if (sgC) decisions.sgCompensation = sgC.value;
                if (sgP) decisions.sgPreDeparture = parseInt(sgP.value) || 0;
                if (duA) decisions.duAssignment = duA.value;
                if (duC) decisions.duCompensation = duC.value;
                if (duP) decisions.duPreDeparture = parseInt(duP.value) || 0;
                if (nbiA) decisions.nbiAssignment = nbiA.value;
                if (nbiC) decisions.nbiCompensation = nbiC.value;
                if (nbiP) decisions.nbiPreDeparture = parseInt(nbiP.value) || 0;

                var totalPreDep = decisions.sgPreDeparture + decisions.duPreDeparture + decisions.nbiPreDeparture;
                if (totalPreDep > 150000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('predep_over_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var cbSG = document.getElementById('culturalBudgetSG');
                var cbDU = document.getElementById('culturalBudgetDU');
                var cbNBI = document.getElementById('culturalBudgetNBI');
                var cSG = document.getElementById('correctionSG');
                var cDU = document.getElementById('correctionDU');
                var cNBI = document.getElementById('correctionNBI');

                if (cbSG) decisions.culturalBudgetSG = parseInt(cbSG.value) || 0;
                if (cbDU) decisions.culturalBudgetDU = parseInt(cbDU.value) || 0;
                if (cbNBI) decisions.culturalBudgetNBI = parseInt(cbNBI.value) || 0;
                if (cSG) decisions.correctionSG = cSG.value;
                if (cDU) decisions.correctionDU = cDU.value;
                if (cNBI) decisions.correctionNBI = cNBI.value;

                var totalCultural = decisions.culturalBudgetSG + decisions.culturalBudgetDU + decisions.culturalBudgetNBI;
                if (totalCultural !== 320000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('cultural_budget_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var rc = document.getElementById('repatCareer');
                var rk = document.getElementById('repatKnowledge');
                var rs = document.getElementById('repatSocial');
                var rr = document.getElementById('repatRole');
                var lSG = document.getElementById('localizeSG');
                var lDU = document.getElementById('localizeDU');
                var lNBI = document.getElementById('localizeNBI');

                if (rc) decisions.repatCareer = parseInt(rc.value) || 0;
                if (rk) decisions.repatKnowledge = parseInt(rk.value) || 0;
                if (rs) decisions.repatSocial = parseInt(rs.value) || 0;
                if (rr) decisions.repatRole = parseInt(rr.value) || 0;
                if (lSG) decisions.localizeSG = lSG.value;
                if (lDU) decisions.localizeDU = lDU.value;
                if (lNBI) decisions.localizeNBI = lNBI.value;

                var totalRepat = decisions.repatCareer + decisions.repatKnowledge + decisions.repatSocial + decisions.repatRole;
                if (totalRepat !== 180000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('repat_budget_warning_msg'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = {};

            if (period === 1) {
                results = this._calculateRound1(d, ds);
            } else if (period === 2) {
                results = this._calculateRound2(d, ds);
            } else if (period === 3) {
                results = this._calculateRound3(d, ds);
            }

            ds.globalScoreHistory.push(results.globalScore || 0);
            ds.costHistory.push(results.roundCost || 0);
            ds.retentionHistory.push(ds.talentRetention);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return results;
        }

        _calculateRound1(d, ds) {
            var markets = ['sg', 'du', 'nbi'];
            var totalCost = 0;
            var totalKT = 0;
            var totalCCA = 0;
            var incidents = 0;

            for (var i = 0; i < markets.length; i++) {
                var m = markets[i];
                var profile = this.MARKET_PROFILES[m];
                var assignType = d[m + 'Assignment'];
                var compType = d[m + 'Compensation'];
                var preDep = d[m + 'PreDeparture'] || 0;

                var baseCost = 0;
                var kt = 0;
                if (assignType === 'lta') { baseCost = profile.ltaCost; kt = profile.ltaKT; }
                else if (assignType === 'shortterm') { baseCost = profile.shortCost; kt = profile.shortKT; }
                else if (assignType === 'virtual') { baseCost = profile.virtualCost; kt = profile.virtualKT; }
                else { baseCost = profile.localCost; kt = profile.localKT; }

                var compMod = this.COMP_MODIFIERS[compType] || this.COMP_MODIFIERS.balancesheet;
                if (assignType !== 'lta') {
                    compMod = { costMult: 1.0, retention: 0, equity: 0 };
                }

                var marketCost = Math.round(baseCost * compMod.costMult) + preDep;
                totalCost += marketCost;

                var ccaScore = profile.ccaBase;
                var preDepBonus = Math.round((preDep / 50000) * 20);
                ccaScore = Math.min(100, ccaScore + preDepBonus + compMod.retention);

                if (assignType === 'virtual' || assignType === 'localhire') {
                    ccaScore = Math.min(100, ccaScore + 15);
                }

                var localLeg = ds[m].localLegitimacy;
                if (assignType === 'localhire') localLeg += 25;
                else if (assignType === 'virtual') localLeg += 15;
                else if (assignType === 'shortterm') localLeg += 5;

                if (ccaScore < 50) incidents += 2;
                else if (ccaScore < 65) incidents += 1;

                ds[m].knowledgeTransfer = kt;
                ds[m].ccaScore = ccaScore;
                ds[m].localLegitimacy = Math.min(100, localLeg);
                ds[m].assignmentType = assignType;
                ds[m].costSpent = marketCost;
            }

            ds.budgetRemaining = ds.totalBudget - totalCost - ds.adminBudget;
            ds.crossCulturalIncidents = incidents;

            totalKT = Math.round((ds.sg.knowledgeTransfer + ds.du.knowledgeTransfer + ds.nbi.knowledgeTransfer) / 3);
            totalCCA = Math.round((ds.sg.ccaScore + ds.du.ccaScore + ds.nbi.ccaScore) / 3);

            var launchScore = Math.round(totalKT * 0.6 + totalCCA * 0.25 + (100 - incidents * 15) * 0.15);
            ds.marketLaunchScore = Math.max(0, Math.min(100, launchScore));

            ds.totalCostScore = totalCost <= ds.assignmentBudget ? Math.round(100 - ((totalCost / ds.assignmentBudget - 0.7) * 100)) : Math.max(0, Math.round(100 - ((totalCost - ds.assignmentBudget) / ds.assignmentBudget) * 200));
            ds.totalCostScore = Math.max(0, Math.min(100, ds.totalCostScore));

            ds.globalIntegration = totalKT;

            var globalScore = Math.round(ds.marketLaunchScore * 0.35 + ds.talentRetention * 0.25 + ds.totalCostScore * 0.20 + Math.max(0, 100 - incidents * 20) * 0.20);

            ds.currentEvent = this.EVENTS[0];

            return {
                period: 1,
                roundCost: totalCost,
                marketLaunch: ds.marketLaunchScore,
                talentRetention: ds.talentRetention,
                costScore: ds.totalCostScore,
                incidents: incidents,
                globalScore: Math.min(100, Math.max(0, globalScore)),
                sgKT: ds.sg.knowledgeTransfer,
                duKT: ds.du.knowledgeTransfer,
                nbiKT: ds.nbi.knowledgeTransfer,
                budgetRemaining: ds.budgetRemaining
            };
        }

        _calculateRound2(d, ds) {
            var markets = ['sg', 'du', 'nbi'];
            var totalCorrectionCost = 0;
            var incidents = ds.crossCulturalIncidents;

            for (var i = 0; i < markets.length; i++) {
                var m = markets[i];
                var profile = this.MARKET_PROFILES[m];
                var budget = d['culturalBudget' + m.charAt(0).toUpperCase() + m.slice(1)] || d['culturalBudget' + m.toUpperCase()] || 0;
                var correction = d['correction' + m.charAt(0).toUpperCase() + m.slice(1)] || d['correction' + m.toUpperCase()] || 'maintain';

                var ccaImprovement = Math.round((budget / 320000) * 25 * (profile.culturalDistance / 5));
                ds[m].ccaScore = Math.min(100, ds[m].ccaScore + ccaImprovement);

                var corrEffect = this.CORRECTION_EFFECTS[correction] || this.CORRECTION_EFFECTS.maintain;
                totalCorrectionCost += corrEffect.cost;
                ds[m].knowledgeTransfer = Math.max(0, Math.min(100, ds[m].knowledgeTransfer + corrEffect.kt));
                ds[m].localLegitimacy = Math.max(0, Math.min(100, ds[m].localLegitimacy + corrEffect.localLeg));
                ds[m].ccaScore = Math.max(0, Math.min(100, ds[m].ccaScore + corrEffect.ccaBoost));

                if (ds[m].ccaScore < 55) incidents += 1;
                if (correction === 'reassign') incidents += 1;
            }

            ds.budgetRemaining -= (320000 + totalCorrectionCost);
            ds.crossCulturalIncidents = incidents;

            var avgKT = Math.round((ds.sg.knowledgeTransfer + ds.du.knowledgeTransfer + ds.nbi.knowledgeTransfer) / 3);
            var avgCCA = Math.round((ds.sg.ccaScore + ds.du.ccaScore + ds.nbi.ccaScore) / 3);

            ds.marketLaunchScore = Math.max(0, Math.min(100, Math.round(avgKT * 0.55 + avgCCA * 0.30 + (100 - incidents * 12) * 0.15)));

            var retentionDelta = Math.round((avgCCA - 60) * 0.5);
            ds.talentRetention = Math.max(30, Math.min(100, ds.talentRetention + retentionDelta));

            ds.globalIntegration = avgKT;

            var totalSpent = ds.totalBudget - ds.budgetRemaining;
            ds.totalCostScore = totalSpent <= ds.totalBudget ? Math.round(100 - ((totalSpent / ds.totalBudget - 0.6) * 120)) : Math.max(0, Math.round(100 - ((totalSpent - ds.totalBudget) / ds.totalBudget) * 200));
            ds.totalCostScore = Math.max(0, Math.min(100, ds.totalCostScore));

            var globalScore = Math.round(ds.marketLaunchScore * 0.35 + ds.talentRetention * 0.25 + ds.totalCostScore * 0.20 + Math.max(0, 100 - incidents * 15) * 0.20);

            ds.currentEvent = this.EVENTS[1];

            return {
                period: 2,
                roundCost: 320000 + totalCorrectionCost,
                marketLaunch: ds.marketLaunchScore,
                talentRetention: ds.talentRetention,
                costScore: ds.totalCostScore,
                incidents: incidents,
                globalScore: Math.min(100, Math.max(0, globalScore)),
                avgCCA: avgCCA,
                avgKT: avgKT,
                budgetRemaining: ds.budgetRemaining
            };
        }

        _calculateRound3(d, ds) {
            var repatCareer = d.repatCareer || 0;
            var repatKnowledge = d.repatKnowledge || 0;
            var repatSocial = d.repatSocial || 0;
            var repatRole = d.repatRole || 0;

            var roleMapRatio = repatRole / 180000;
            var careerRatio = repatCareer / 180000;
            var knowledgeRatio = repatKnowledge / 180000;
            var socialRatio = repatSocial / 180000;

            var retentionBoost = Math.round(roleMapRatio * 30 + careerRatio * 15 + socialRatio * 10 + knowledgeRatio * 5);
            ds.talentRetention = Math.max(30, Math.min(100, ds.talentRetention + retentionBoost));

            var globalLearning = Math.round(knowledgeRatio * 40 + careerRatio * 20);

            var markets = ['sg', 'du', 'nbi'];
            var localizations = { aggressive: 20, moderate: 10, minimal: -5 };

            for (var i = 0; i < markets.length; i++) {
                var m = markets[i];
                var locKey = 'localize' + m.charAt(0).toUpperCase() + m.slice(1);
                var locValue = d[locKey] || d['localize' + m.toUpperCase()] || 'moderate';
                var locBonus = localizations[locValue] || 10;

                ds[m].localLegitimacy = Math.max(0, Math.min(100, ds[m].localLegitimacy + locBonus));

                if (locValue === 'aggressive') {
                    ds[m].knowledgeTransfer = Math.max(0, ds[m].knowledgeTransfer - 8);
                } else if (locValue === 'minimal') {
                    ds[m].knowledgeTransfer = Math.min(100, ds[m].knowledgeTransfer + 5);
                }
            }

            ds.budgetRemaining -= 180000;

            var avgKT = Math.round((ds.sg.knowledgeTransfer + ds.du.knowledgeTransfer + ds.nbi.knowledgeTransfer) / 3);
            var avgLocalLeg = Math.round((ds.sg.localLegitimacy + ds.du.localLegitimacy + ds.nbi.localLegitimacy) / 3);

            ds.marketLaunchScore = Math.max(0, Math.min(100, Math.round(avgKT * 0.45 + avgLocalLeg * 0.35 + ds.talentRetention * 0.20)));
            ds.globalIntegration = avgKT;

            var totalSpent = ds.totalBudget - ds.budgetRemaining;
            ds.totalCostScore = totalSpent <= ds.totalBudget ? Math.round(100 - ((totalSpent / ds.totalBudget - 0.6) * 120)) : Math.max(0, Math.round(100 - ((totalSpent - ds.totalBudget) / ds.totalBudget) * 200));
            ds.totalCostScore = Math.max(0, Math.min(100, ds.totalCostScore));

            var incidents = ds.crossCulturalIncidents;
            var globalScore = Math.round(ds.marketLaunchScore * 0.35 + ds.talentRetention * 0.25 + ds.totalCostScore * 0.20 + Math.max(0, 100 - incidents * 12) * 0.20);

            return {
                period: 3,
                roundCost: 180000,
                marketLaunch: ds.marketLaunchScore,
                talentRetention: ds.talentRetention,
                costScore: ds.totalCostScore,
                incidents: incidents,
                globalScore: Math.min(100, Math.max(0, globalScore)),
                globalIntegration: ds.globalIntegration,
                localLegitimacy: avgLocalLeg,
                globalLearning: globalLearning,
                budgetRemaining: ds.budgetRemaining
            };
        }

        _updateBriefing(state) {
            var period = Math.min((state.currentPeriod || 1), 3);

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            var briefTitle = document.getElementById('briefingTitle');
            var briefText = document.getElementById('briefingText');
            var eventPanel = document.getElementById('eventPanel');
            var eventTitle = document.getElementById('eventTitle');
            var eventText = document.getElementById('eventText');

            if (r1) r1.style.display = period === 1 ? 'block' : 'none';
            if (r2) r2.style.display = period === 2 ? 'block' : 'none';
            if (r3) r3.style.display = period === 3 ? 'block' : 'none';

            var ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null;

            if (period === 1) {
