        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var scores = history.map(function(r) { return r.results ? r.results.globalScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var finalScore = lastResult.globalScore || 0;

            var performance = 'Developing Global HR Capability';
            if (finalScore >= 75) performance = 'Excellent Global Talent Leader';
            else if (finalScore >= 60) performance = 'Competent Mobility Manager';
            else if (finalScore >= 45) performance = 'Emerging IHRM Practitioner';

            var insights = [];
            if (lastResult.talentRetention >= 80) {
                insights.push('Strong talent retention strategy. Repatriation investment paid off.');
            }
            if (lastResult.talentRetention < 60) {
                insights.push('Talent retention is weak. Consider investing more in role mapping and career planning for returnees.');
            }
            if (lastResult.marketLaunch >= 70) {
                insights.push('Market launch execution was effective across the three hubs.');
            }
            if (lastResult.marketLaunch < 50) {
                insights.push('Market launch scores are low. Assignment type selection and knowledge transfer need improvement.');
            }
            if (lastResult.incidents > 3) {
                insights.push('Cross-cultural incidents were frequent. Pre-departure preparation and cultural integration budgets were likely insufficient.');
            }
            if (insights.length === 0) {
                insights.push('Balanced approach across all dimensions. Review individual market scores for optimization opportunities.');
            }

            return {
                finalGlobalScore: finalScore,
                averageScore: avgScore,
                performance: performance,
                insights: insights
            };
        }

