            if (!results) return null;
            var period = results.period;

            if (period === 1) {
                if (results.incidents >= 3) return window.mySimulation.t('hint_high_incidents');
                if (results.costScore < 40) return window.mySimulation.t('hint_over_budget');
                if (results.marketLaunch < 50) return window.mySimulation.t('hint_low_launch');
                return window.mySimulation.t('hint_r1_ok');
            }
            if (period === 2) {
                if (results.avgCCA < 60) return window.mySimulation.t('hint_low_cca');
                if (results.talentRetention < 60) return window.mySimulation.t('hint_low_retention');
                return window.mySimulation.t('hint_r2_ok');
            }
            if (period === 3) {
                if (results.talentRetention < 65) return window.mySimulation.t('hint_repat_risk');
                return window.mySimulation.t('hint_r3_ok');
            }
            return null;
        }

